 const support=$('#placeSupport');if(support)support.onchange=()=>placementSupportId=support.value;
 const bind=(id,fn)=>{const el=$('#'+id);if(el)el.onchange=()=>{try{commit('환경 변경',()=>fn(realStage(),el.value))}catch(e){toast(e.message);renderAll()}}};
