function scatterAt(st,w){const a=project.library.find(x=>x.id===placementAssetId)||project.library.find(x=>x.category==='vegetation');if(!a)return;if(placementDepthLayer!=='L1'&&(a.collision.length||a.interactionType))return;const radius=+($('#brushRange')?.value||220),r=seeded(Math.floor(w.x*31+w.y*17+st.elements.length+st.environment.placements.length));commit('Scatter 요소',()=>{for(let i=0;i<5;i++){const ang=r()*Math.PI*2,rr=Math.sqrt(r())*radius,x=w.x+Math.cos(ang)*rr;if(placementDepthLayer!=='L1'){const e=HonroEnvironment.place(st,a,{id:uid('scenery'),localX:x,scale:.85+r()*.3,depthLayer:placementDepthLayer,groupId:placementGroup(st)?.id,supportId:placementSupportId||undefined});st.environment.placements.push(e);continue}const xx=clamp(x,0,st.width),sf=nearestSurface(st,xx,w.y);if(!sf)continue;const e={id:uid('el'),assetId:a.id,x:xx,y:sf.y,rotation:(r()-.5)*.28,scale:.75+r()*.65,layer:a.layer||(a.collision.length?'interactive':'back'),depthLayer:'L1',snap:true,scatter:true};if(st.elements.some(o=>dist(o,e)<35))continue;st.elements.push(e)}})}

function elementPointerDown(e,p){const raw=screenToWorld(dom.elementCanvas,e.offsetX,e.offsetY,elementView),w=e.ctrlKey?gridSnapPoint(raw):raw,a=activeAsset();if(e.button===1||e.button===2){p.pan=true;return}if(elementTool==='polygon'){if(e.detail<2){elementPolygonDraft.push({...w});renderElement()}return}if(elementTool==='anchor'){commit('Anchor 설정',()=>{a.anchor={x:w.x,y:w.y}});elementTool='point';return}if(elementTool==='socket'){commit('Socket 추가',()=>{a.sockets.push({id:`socket_${a.sockets.length+1}`,x:w.x,y:w.y})});elementTool='point';return}if(a.vector){selectedNode=-1;selectedShapeIndex=-1;renderElement();return}selectedNode=nearestAssetNode(a,raw,10/elementView.zoom);if(selectedNode>=0){p.dragNode=true;selectedShapeIndex=nodeByGlobal(a,selectedNode)?.shapeIndex??selectedShapeIndex;return}for(let i=a.visual.length-1;i>=0;i--)if(pointInPoly(raw,a.visual[i].points)){selectedShapeIndex=i;p.dragShape=true;p.startWorld=raw;p.originShape=deep(a.visual[i].points);renderElement();return}selectedShapeIndex=-1;renderElement()}
function elementPointerMove(e,p){if(p.pan){elementView.x-=(e.offsetX-p.lastX)/elementView.zoom;elementView.y-=(e.offsetY-p.lastY)/elementView.zoom;renderElement();return}const raw=screenToWorld(dom.elementCanvas,e.offsetX,e.offsetY,elementView),w=e.ctrlKey?gridSnapPoint(raw):raw;if(p.dragNode&&selectedNode>=0){const n=nodeByGlobal(activeAsset(),selectedNode);if(n){n.point.x=w.x;n.point.y=w.y;selectedShapeIndex=n.shapeIndex;syncAssetCollision(activeAsset());renderElement()}}else if(p.dragShape&&selectedShapeIndex>=0){const sh=activeAsset().visual[selectedShapeIndex],g=project.settings.grid||40,dx=e.ctrlKey?Math.round((raw.x-p.startWorld.x)/g)*g:raw.x-p.startWorld.x,dy=e.ctrlKey?Math.round((raw.y-p.startWorld.y)/g)*g:raw.y-p.startWorld.y;sh.points=p.originShape.map(q=>({x:q.x+dx,y:q.y+dy}));syncAssetCollision(activeAsset());renderElement()}}
function elementPointerUp(e,p){if(p.dragNode||p.dragShape){commit('Edit geometry',()=>{},p.before)}}
function elementDoubleClick(e){if(activeAsset().vector)return;if(elementTool==='polygon'){finalizeElementPolygon();return}const a=activeAsset(),raw=screenToWorld(dom.elementCanvas,e.offsetX,e.offsetY,elementView),w=e.ctrlKey?gridSnapPoint(raw):raw;let best=null,d=Infinity;for(const sh of a.visual)for(let i=0;i<sh.points.length;i++){const p=sh.points[i],q=sh.points[(i+1)%sh.points.length],hit=pointSegmentDistance(w,p,q);if(hit.d<d){d=hit.d;best={sh,i,point:hit.point}}}if(best&&d<12/elementView.zoom)commit('Vertex 추가',()=>{best.sh.points.splice(best.i+1,0,e.ctrlKey?gridSnapPoint(best.point):best.point);syncAssetCollision(a)})}
function finalizeElementPolygon(){if(activeAsset().vector)return;if(elementTool!=='polygon'||elementPolygonDraft.length<3)return;const pts=elementPolygonDraft.map(p=>({...p}));elementPolygonDraft=[];commit('Element polygon 추가',()=>{const a=activeAsset(),base=a.visual[selectedShapeIndex]||a.visual[0];a.visual.push(shape(pts,base?.fill||'#5b625e',base?.stroke||'#222d30',base?.alpha??1));selectedShapeIndex=a.visual.length-1;syncAssetCollision(a)});elementTool='point';renderAll()}
function nearestAssetNode(a,w,rad){let k=0,best=-1,d=Infinity;for(const sh of a.visual)for(const p of sh.points){const dd=dist(p,w);if(dd<d&&dd<rad){d=dd;best=k}k++}return best}
function pointSegmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,n=dx*dx+dy*dy,t=n?clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/n,0,1):0,q={x:a.x+dx*t,y:a.y+dy*t};return{d:dist(p,q),point:q}}

function resetPlay(from='start'){
 if(playFrame)stopPlay(false);
 const snapshot=deep(project),st=snapshot.stages.find(s=>s.id===snapshot.activeStageId);
 playSnapshot={stageView:deep(stageView),elementView:deep(elementView),selected:deep(selected),selectedNode,selectedShapeIndex,tool};
 const frame=document.createElement('iframe');frame.id='runtimeFrame';frame.title='HONRO 실제 게임 플레이테스트';frame.allow='autoplay; fullscreen';
 const base=document.baseURI.replace(/[&"<>]/g,c=>({'&':'&amp;','"':'&quot;','<':'&lt;','>':'&gt;'}[c]));
 const head='<base href="'+base+'"><script>globalThis.HONRO_EMBEDDED=true;<'+ '/script>';
 frame.srcdoc=HONRO_PLAYTEST_HTML.replace('<head>','<head>'+head);
 playFrame=frame;playState={from,stageId:st.id};
 playReady=new Promise((resolve,reject)=>{frame.onload=()=>{try{
  const app=frame.contentWindow.HonroApp;app.launchMap(snapshot,st.id,{from,unitId:selected?.type==='unit'?selected.id:null,camera:deep(stageView)});
  frame.contentWindow.focus();resolve(app);
 }catch(e){toast('Playtest: '+e.message);reject(e);}};});
 $('#runtimeHost').replaceChildren(frame);playReady.catch(()=>{});return playReady;
}
function stopPlay(returnToStage=true){
 if(playFrame){try{playFrame.contentWindow.HonroApp?.audio?.dispose?.()}catch{}playFrame.remove();}
 playFrame=null;playState=null;playReady=null;
 if(playSnapshot){({stageView,elementView,selected,selectedNode,selectedShapeIndex,tool}=playSnapshot);playSnapshot=null;}
 if(returnToStage)switchTab('stage');
}
function renderPlay(){}
function loop(ts){if(currentTab==='stage')renderStage();requestAnimationFrame(loop)}

function renderToolbars(){const host=$('#stageToolbar');if(host)host.innerHTML=[['select','선택'],['terrain','지형'],['solid','Solid'],['material','재질'],['place','배치'],['scatter','Scatter'],['unit','유닛'],['event','이벤트'],['pan','Pan']].map(([id,n])=>`<button class="tool ${tool===id?'active':''}" data-tool="${id}">${n}</button>`).join('<span class="toolbar-sep"></span>');$$('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;if(tool!=='solid')solidDraft=[];renderAll()});const eh=$('#elementToolbar');if(eh)eh.innerHTML=[['point','Point'],['polygon','Polygon'],['anchor','Anchor'],['socket','Socket']].map(([id,n])=>`<button class="tool ${elementTool===id?'active':''}" data-etool="${id}" ${activeAsset().vector&&['point','polygon'].includes(id)?'disabled title="SVG 원본에서 경로를 편집하세요"':''}>${n}</button>`).join('');$$('[data-etool]').forEach(b=>b.onclick=()=>{elementTool=b.dataset.etool;if(elementTool!=='polygon')elementPolygonDraft=[];renderAll()})}
function validateStage(st){return HonroMaps.validate({...activeProject(),stages:[st]})}

