function materialRuntimeKind(k){return({water:'shallow-water',rock:'exposed-rock',grass:'grass-mass',moss:'moss',mud:'mud-track',charred:'charred-soil',stone:'stone-road'}[k]||k)}
function downloadProject(){download(`${safe(project.name)}.honro-map.json`,JSON.stringify(project,null,2),'application/json')}
