function agentContext(){const st=realStage();return{workshop:'HONRO Workshop 3',stage:{id:st.id,name:st.name,width:st.width,height:st.height,backdrop:st.backdrop},counts:{terrains:st.terrains.length,materials:st.materials.length,elements:st.elements.length,units:st.units.length,events:st.events.length,...sceneStats(st)},selection:selected,availableAssets:project.library.map(a=>({id:a.id,name:a.name,category:a.category,tags:a.tags,collision:!!a.collision.length,nodes:assetNodeCount(a)})),commandAPI:['world.set','stage.update','object.update','asset.add','terrain.add','terrain.addSolid','terrain.roughen','terrain.moveNode','terrain.optimize','material.paint','element.place','element.move','element.delete','element.scatter','asset.optimize','asset.update','unit.place','unit.update','unit.move','event.place','encounter.add','objective.add','move','rotate','scale','rename','delete',...Object.keys(HonroCommands.aliases)],availableUnits:HonroUnits.catalog(),validation:validateStage(st)}}
async function copyAgentContext(){await navigator.clipboard.writeText(JSON.stringify(agentContext(),null,2));toast('Agent context 복사 완료')}
function previewCommands(cmds){previewProject=applyCommands(project,cmds);previewCommandsKey=JSON.stringify(cmds);invalidateRuntime();renderStage();return diffSummary(project,previewProject)}
function applyPreview(){if(!previewProject)throw Error('No change set preview');const next=previewProject;commit('Agent changes',p=>Object.assign(p,next));previewCommandsKey=null;return deep(project)}
function clearPreview(){previewProject=null;previewCommandsKey=null;invalidateRuntime();renderStage()}
function runAgent(apply){try{let cmds=JSON.parse($('#agentCommands').value);if(!Array.isArray(cmds))cmds=[cmds];if(!previewProject||previewCommandsKey!==JSON.stringify(cmds))previewCommands(cmds);const summary=diffSummary(project,previewProject);if(apply)applyPreview();$('#changes').innerHTML=summary.map(x=>esc(x)).join('<br>')}catch(e){$('#changes').textContent=e.message}}

function applyCommands(p,cmds){return HonroCommands.apply(p,cmds)}

function diffSummary(a,b){const sa=a.stages.find(s=>s.id===a.activeStageId),sb=b.stages.find(s=>s.id===b.activeStageId),out=[];if(sa.width!==sb.width||sa.height!==sb.height)out.push(`World ${sa.width}×${sa.height} → ${sb.width}×${sb.height}`);for(const k of ['terrains','materials','elements','units','events']){const d=sb[k].length-sa[k].length;if(d)out.push(`${k}: ${d>0?'+':''}${d}`)}return out.length?out:['구조 수 변화 없음 · 속성/위치 변경']}

